import { Ionicons } from '@expo/vector-icons';import { LinearGradient } from 'expo-linear-gradient';import { useEffect, useMemo, useRef, useState } from 'react';import {  ActivityIndicator,  Animated,  Modal,  Pressable,  ScrollView,  StyleSheet,  Switch,  Text,  View} from 'react-native';import { SafeAreaView } from 'react-native-safe-area-context';import Svg, { Circle, Defs, Line, LinearGradient as SvgGradient, Path, Rect, Stop } from 'react-native-svg';import { TimeField } from '../../components/TimeField';import {  getRecommendedActivityAt,  type CircadianBriefing,  type SleepNeedEstimate,  type SleepSession} from '../../engines/circadian';import { fonts, cardSurface } from '../../styles/mobileTheme';
